// Stop hook gate. Claude Code runs this every time Claude tries to stop.
// It lets Claude stop only when:
//   1. .claude/PAUSE exists (you turned the loop off), or
//   2. docs/NEEDS_HUMAN.md exists (Claude is waiting for you), or
//   3. every module in docs/PROGRESS.md is ticked AND the full check is green.
// Otherwise it blocks the stop and tells Claude what to fix or what to build next.
// Ceiling: after MAX_NO_PROGRESS blocks in a row with no new commit and no new ticked
// module, it writes docs/NEEDS_HUMAN.md and lets Claude stop, so the loop never spins forever.
// Do not edit this file from inside the loop.
import { execSync, spawnSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const MAX_NO_PROGRESS = 8;
const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const p = (...a) => join(root, ...a);
const stateFile = p('.claude', 'state', 'gate.json');

const allow = () => process.exit(0);
const block = (reason) => {
  process.stdout.write(JSON.stringify({ decision: 'block', reason }));
  process.exit(0);
};
const read = (f) => (existsSync(f) ? readFileSync(f, 'utf8') : '');
const sh = (cmd) => {
  try { return execSync(cmd, { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim(); }
  catch { return ''; }
};

if (existsSync(p('.claude', 'PAUSE'))) allow();

mkdirSync(p('.claude', 'state'), { recursive: true });
const state = { blocks: 0, head: '', done: -1, maxTests: 0, ...JSON.parse(read(stateFile) || '{}') };

// Waiting for the human: allow the stop and give the loop a fresh ceiling for afterwards.
if (existsSync(p('docs', 'NEEDS_HUMAN.md'))) {
  state.blocks = 0;
  writeFileSync(stateFile, JSON.stringify(state, null, 2));
  allow();
}

const progress = read(p('docs', 'PROGRESS.md'));
const doneIds = [...progress.matchAll(/^- \[x\] (M\d+)/gim)].map((m) => m[1]);
const nextLine = (progress.match(/^- \[ \] (.+)$/m) || [])[1];
const head = sh('git rev-parse HEAD') || 'none';

if (head !== state.head || doneIds.length !== state.done) state.blocks = 0;
state.head = head;
state.done = doneIds.length;

const save = () => writeFileSync(stateFile, JSON.stringify(state, null, 2));
const fail = (reason) => {
  state.blocks += 1;
  if (state.blocks > MAX_NO_PROGRESS) {
    save();
    writeFileSync(p('docs', 'NEEDS_HUMAN.md'),
      `# Loop stopped: no progress\n\nThe gate blocked ${MAX_NO_PROGRESS} stops in a row with no new commit and no new ticked module.\n\nLast reason:\n\n${reason}\n\nRead docs/NOTES.md, fix or answer, then delete this file and tell Claude to continue.\n`);
    allow();
  }
  save();
  block(`${reason}\n\n(Gate block ${state.blocks} of ${MAX_NO_PROGRESS} with no progress. If you are stuck on something only the human can do, write docs/NEEDS_HUMAN.md with the exact question, then stop.)`);
};

// 1. The full check: lint, typecheck, unit, db, build, e2e.
if (!existsSync(p('package.json'))) fail('No package.json yet. Finish M0 setup (see docs/modules.md).');
const run = spawnSync('npm', ['run', 'verify'], { cwd: root, shell: true, encoding: 'utf8', timeout: 25 * 60 * 1000 });
if (run.status !== 0) {
  const out = `${run.stdout || ''}\n${run.stderr || ''}`.trim().split('\n').slice(-80).join('\n');
  fail(`npm run verify is red. Fix the cause (never skip, delete or weaken a test). Last output:\n\n${out}`);
}

// 2. No skipped tests, and the number of tests never goes down.
let total = 0;
const vitest = read(p('reports', 'vitest.json'));
if (vitest) {
  const v = JSON.parse(vitest);
  if ((v.numPendingTests || 0) + (v.numTodoTests || 0) > 0) fail('Vitest has skipped or todo tests. Make them real and passing.');
  total += v.numTotalTests || 0;
}
const e2e = read(p('reports', 'e2e.json'));
if (e2e) {
  const s = JSON.parse(e2e).stats || {};
  if ((s.skipped || 0) > 0) fail('Playwright has skipped tests. Make them real and passing.');
  total += (s.expected || 0) + (s.flaky || 0);
}
const db = read(p('reports', 'db.json'));
if (db) total += JSON.parse(db).passed || 0;
if (total < state.maxTests) fail(`Test count dropped from ${state.maxTests} to ${total}. Put the missing tests back.`);
state.maxTests = Math.max(state.maxTests, total);

// 3. Every ticked module has a PASS review from the reviewer agent.
for (const id of doneIds) {
  const review = read(p('reports', 'reviews', `${id}.md`));
  if (!/VERDICT:\s*PASS/.test(review)) fail(`${id} is ticked but reports/reviews/${id}.md has no "VERDICT: PASS". Run the reviewer agent and fix what it finds.`);
}

// 4. Work is committed.
if (sh('git status --porcelain')) fail('Verify is green but there are uncommitted changes. Commit them with a message like "M3: Manage Tenants (FR-004, FR-005)".');

// 5. More modules to build?
if (nextLine) fail(`All checks green (${total} tests). Next module: ${nextLine}. Read its section in docs/modules.md and keep going.`);

save();
allow();
